INSERT INTO x1(content) VALUES('"See here, young man," said Mulga Bill, "from Walgett to the sea,'); INSERT INTO x1(content) VALUES('From Conroy''s Gap to Castlereagh, there''s none can ride like me.'); INSERT INTO x1(content) VALUES('I''m good all round at everything as everybody knows,'); INSERT INTO x1(content) VALUES('Although I''m not the one to talk -- I hate a man that blows.');